-- CREATE TRIGGER checks a REFERENCING clause after its relation, in
-- PostgreSQL's order and with its error codes.
CREATE TABLE tt_base (a int, b int);
CREATE TABLE tt_parted (a int) PARTITION BY RANGE (a);
CREATE TABLE tt_part PARTITION OF tt_parted FOR VALUES FROM (0) TO (10);
CREATE VIEW tt_view AS SELECT * FROM tt_base;
CREATE FUNCTION tt_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RETURN NULL; END $$;
CREATE TRIGGER t1 BEFORE INSERT ON tt_base REFERENCING NEW TABLE AS n FOR EACH STATEMENT EXECUTE FUNCTION tt_fn();
CREATE TRIGGER t2 AFTER INSERT OR UPDATE ON tt_base REFERENCING NEW TABLE AS n FOR EACH STATEMENT EXECUTE FUNCTION tt_fn();
CREATE TRIGGER t3 AFTER UPDATE OF a ON tt_base REFERENCING NEW TABLE AS n FOR EACH STATEMENT EXECUTE FUNCTION tt_fn();
CREATE TRIGGER t4 AFTER INSERT ON tt_base REFERENCING OLD TABLE AS o FOR EACH STATEMENT EXECUTE FUNCTION tt_fn();
CREATE TRIGGER t5 AFTER DELETE ON tt_base REFERENCING NEW TABLE AS n FOR EACH STATEMENT EXECUTE FUNCTION tt_fn();
CREATE TRIGGER t6 AFTER TRUNCATE ON tt_base REFERENCING NEW TABLE AS n FOR EACH STATEMENT EXECUTE FUNCTION tt_fn();
CREATE TRIGGER t7 AFTER INSERT ON tt_view REFERENCING NEW TABLE AS n FOR EACH STATEMENT EXECUTE FUNCTION tt_fn();
CREATE TRIGGER t8 AFTER INSERT ON tt_part REFERENCING NEW TABLE AS n FOR EACH ROW EXECUTE FUNCTION tt_fn();
CREATE TRIGGER t9 BEFORE INSERT ON tt_part REFERENCING NEW TABLE AS n FOR EACH ROW EXECUTE FUNCTION tt_fn();
CREATE TRIGGER t10 AFTER INSERT ON tt_base REFERENCING NEW TABLE AS n FOR EACH STATEMENT EXECUTE FUNCTION tt_fn();
CREATE TRIGGER t11 AFTER UPDATE ON tt_base REFERENCING OLD TABLE AS o NEW TABLE AS n FOR EACH ROW EXECUTE FUNCTION tt_fn();
SELECT tgname FROM pg_trigger WHERE tgrelid = 'tt_base'::regclass ORDER BY 1;
